import{_ as t,o,c as a,a6 as n}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"Develop TikTools","description":"","frontmatter":{"title":"Develop TikTools","docId":"developer.overview","translationKey":"developer.overview","locale":"en","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"1ee65a70172f8154eeaf60fb1a3069192769582a4ef264426d0aefaf346e8003","translationRevision":"1ee65a70172f8154eeaf60fb1a3069192769582a4ef264426d0aefaf346e8003","order":0},"headers":[],"relativePath":"en/developer/index.md","filePath":"en/developer/index.md","lastUpdated":1794591482000}'),r={name:"en/developer/index.md"};function i(s,e,d,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="develop-tiktools" tabindex="-1">Develop TikTools <a class="header-anchor" href="#develop-tiktools" aria-label="Permalink to &quot;Develop TikTools {#develop-tiktools}&quot;">​</a></h1><p>TikTools keeps one native AppCore behind typed control operations. Vue renders the desktop, local-browser and controller interfaces; Winit/Wry owns desktop windows. The CLI and SDK use the same operations. Start with the <a href="./setup.html">development setup</a>, then choose the smallest loop that covers your change.</p><h2 id="choose-an-entry-point" tabindex="-1">Choose an entry point <a class="header-anchor" href="#choose-an-entry-point" aria-label="Permalink to &quot;Choose an entry point {#choose-an-entry-point}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Work</th><th>Entry point</th><th>What it establishes</th></tr></thead><tbody><tr><td>Vue components and stores</td><td>Vite, Vitest and the injected ControlClient</td><td>Interface behavior; no native window validation.</td></tr><tr><td>Desktop integration</td><td><code>bun run start</code></td><td>Development WebView and IPC integration.</td></tr><tr><td>Native services</td><td>Targeted Cargo tests</td><td>Core contracts, persistence and service behavior.</td></tr><tr><td>Headless browser access</td><td><code>bun run dev</code></td><td>A native host, local adapter and Vite with pairing.</td></tr><tr><td>Documentation</td><td><code>bun scripts/task.ts docs dev</code></td><td>Markdown and isolated VitePress build.</td></tr><tr><td>Public demo</td><td>Separate demo entry and simulated transport</td><td>Fictional deterministic scenarios, not upstream services.</td></tr></tbody></table><h2 id="source-ownership" tabindex="-1">Source ownership <a class="header-anchor" href="#source-ownership" aria-label="Permalink to &quot;Source ownership {#source-ownership}&quot;">​</a></h2><ul><li><code>crates/tiktools-core</code>: services, operations and SQLite. It does not depend on a WebView.</li><li><code>crates/tiktools-control-api</code>: registry, JSON-RPC routing, IPC and discovery.</li><li><code>crates/tiktools-desktop</code>: Winit/Wry, UI-thread bridge, lifecycle and packaged assets.</li><li><code>src/web/app</code>: bootstrap, router and shell. <code>pages</code> compose <code>widgets</code> and <code>features</code>; <code>entities</code> own domain stores/contracts; <code>shared</code> holds reusable UI and infrastructure.</li><li><code>src/automation/contracts/generated</code>: versioned frontend event contracts generated from Rust. Do not retype these schemas in a demo or guide.</li><li><code>packages</code>: the existing TypeScript plugin SDK/UI packages. Plugin implementations live in the external plugins repository.</li></ul><h2 id="contribution-boundary" tabindex="-1">Contribution boundary <a class="header-anchor" href="#contribution-boundary" aria-label="Permalink to &quot;Contribution boundary {#contribution-boundary}&quot;">​</a></h2><p>Keep native, local-browser, remote-controller and demo entry points explicit. Absence of a native host is an error in a real entry point; it must not silently select a mock. Dispose listeners, subscriptions and timers with the owning scope. Keep Rust/Bun lockfiles and required CI gates intact.</p><p>User installation belongs in the <a href="./../user/installation.html">user guide</a>. These development checks do not establish real TikTok connectivity, OBS rendering, native WebView compatibility or two-computer collaboration by themselves.</p>',9)])])}const b=t(r,[["render",i]]);export{u as __pageData,b as default};
